 async native(id,type='picture-entity'){if(!this.c.state(id))return;this._native={id,type};this._nativeError='';this._nativeCard=null;const epoch=++this._nativeEpoch;await this.updateComplete;try{if(!globalThis.loadCardHelpers)throw new Error(this.t.nativeUnavailable);const helpers=await loadCardHelpers();if(epoch!==this._nativeEpoch||!this.c.state(id))return;const card=helpers.createCardElement({type,entity:id,...(type==='picture-entity'?{camera_view:'live',show_name:false,show_state:false}:{})});card.hass=this.c.hass;const host=this.renderRoot.querySelector('.camera-host');if(host){host.replaceChildren(card);this._nativeCard=card;}}catch(e){this._nativeError=String(e.message||e);}}
